#!/usr/bin/env bash
# ==============================================================================
# Local Validation Script for Adaptive Adversarial Training Model
#
# Usage:
#   bash val_adv_local.sh [WEIGHTS] [ATTACKS] [ATTACK_WEIGHTS] [DATA]
#
# Examples:
#   1. Default: Test all 5 settings (raw, pgd, bim, mim, worstk) in White-Box:
#      bash val_adv_local.sh
#
#   2. Test a single attack (e.g. pgd):
#      bash val_adv_local.sh "" pgd
#
#   3. Test Black-Box attack (generated by pretrained yolo12l.pt):
#      bash val_adv_local.sh "" "pgd bim mim" yolo12l.pt
#
#   4. Test on validation split instead of test split:
#      bash val_adv_local.sh "" "raw pgd bim mim worstk" current coco_train_traffic5k.yaml
# ==============================================================================

set -euo pipefail

ROOT="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
cd "$ROOT"

# Check & activate local virtual environment
if [[ -f "$ROOT/.yolo_env/bin/activate" ]]; then
  source "$ROOT/.yolo_env/bin/activate"
else
  echo "WARNING: .yolo_env virtual environment not found; using active Python environment." >&2
fi

# Environment settings for local execution
export OPENBLAS_NUM_THREADS=1
export MKL_NUM_THREADS=1
export NUMEXPR_NUM_THREADS=1
export OMP_NUM_THREADS="${OMP_NUM_THREADS:-4}"
export PYTORCH_CUDA_ALLOC_CONF="expandable_segments:True,garbage_collection_threshold:0.8"
export PYTHONUNBUFFERED=1

if [[ "${1:-}" == "-h" || "${1:-}" == "--help" ]]; then
  echo "Usage: bash val_adv_local.sh [WEIGHTS] [ATTACKS] [ATTACK_WEIGHTS] [DATA]"
  echo ""
  echo "Arguments:"
  echo "  WEIGHTS         Model checkpoint (.pt). Defaults to adaptive AT best.pt"
  echo "  ATTACKS         Space-separated list of attacks to test (default: 'raw pgd bim mim worstk')"
  echo "  ATTACK_WEIGHTS  'current' for white-box, or surrogate model (e.g. 'yolo12l.pt') for black-box"
  echo "  DATA            Dataset YAML (default: 'coco_train_traffic5k_test.yaml')"
  echo ""
  echo "Examples:"
  echo "  bash val_adv_local.sh                                     # Full benchmark on all 5 attacks (white-box)"
  echo "  bash val_adv_local.sh \"\" pgd                              # Single attack (pgd, white-box)"
  echo "  bash val_adv_local.sh \"\" \"pgd bim mim\" yolo12l.pt         # Black-box transfer attack"
  echo "  bash val_adv_local.sh \"\" raw current coco_train_traffic5k.yaml  # Evaluate clean on validation split"
  exit 0
fi

# ================= Configuration =================
# 1. Model weights to evaluate (defaults to the adaptive adversarial training checkpoint)
DEFAULT_WEIGHTS="runs/local_adv_adaptive_current_coco_train_traffic5k_ep100_pgd_bim_mim_worstk_0.10_0.10_0.40_0.15/weights/best.pt"
WEIGHTS="${1:-"${WEIGHTS:-$DEFAULT_WEIGHTS}"}"

# 2. Attacks to test (default: all attacks used in the adaptive training + clean raw)
# Options: raw, pgd, bim, mim, worstk, cw, autoattack, uap
ATTACKS="${2:-"${ATTACKS:-raw pgd bim mim worstk}"}"

# 3. Attack generator weights:
#    - "current" / empty: White-Box attack (attacks generated on the evaluated model itself)
#    - "yolo12l.pt" etc.: Black-Box / Transfer attack (attacks generated on surrogate model)
ATTACK_WEIGHTS="${3:-"${ATTACK_WEIGHTS:-yolo12l.pt}"}"

# 4. Dataset configuration:
#    - coco_train_traffic5k_test.yaml: Dedicated 500-sample test set (recommended for generalization benchmark)
#    - coco_train_traffic5k.yaml: 500-sample val set (used during training)
DATA="${4:-"${DATA:-coco_train_traffic5k_test.yaml}"}"

# 5. Traffic categories (10 classes from COCO used during training)
CLASSES=(0 1 2 3 5 6 7 9 11 12)

# 6. Evaluation hyperparameters
BATCH="${BATCH:-16}"
IMGSZ="${IMGSZ:-640}"
DEVICE="${DEVICE:-0}"
WORSTK_K="${WORSTK_K:-10}"
PROJECT="${PROJECT:-runs/val_adv}"

# ================= Sanity Checks =================
if [[ ! -f "$WEIGHTS" ]]; then
  echo "ERROR: Model weights checkpoint not found: $WEIGHTS" >&2
  exit 1
fi

# Resolve dataset yaml path
if [[ ! -f "$DATA" && -f "$ROOT/ultralytics/cfg/datasets/$DATA" ]]; then
  DATA="$ROOT/ultralytics/cfg/datasets/$DATA"
elif [[ ! -f "$DATA" ]]; then
  echo "ERROR: Dataset YAML not found: $DATA" >&2
  exit 1
fi

# Determine source tag (white-box vs black-box)
if [[ -z "$ATTACK_WEIGHTS" || "$ATTACK_WEIGHTS" == "current" || "$ATTACK_WEIGHTS" == "none" ]]; then
  ATT_SRC_TAG="wb"
else
  SURROGATE_NAME="${ATTACK_WEIGHTS##*/}"
  ATT_SRC_TAG="bb_${SURROGATE_NAME%.pt}"
fi

MODEL_TAG="${WEIGHTS##*/}"
MODEL_TAG="${MODEL_TAG%.pt}"
EXP_TAG="val_adaptive_${ATT_SRC_TAG}"

# Setup logging
mkdir -p logs
TIMESTAMP="$(date +%Y%m%d-%H%M%S)"
LOG_FILE="logs/${EXP_TAG}-${TIMESTAMP}.log"
exec > >(tee -a "$LOG_FILE") 2>&1

echo "=========================================================="
echo "Adaptive AT Model Validation"
echo "Start Time:     $(date)"
echo "Detector Model: $WEIGHTS"
echo "Dataset:        $DATA"
echo "Classes:        ${CLASSES[*]}"
echo "Attack Source:  $ATTACK_WEIGHTS ($ATT_SRC_TAG)"
echo "Attacks:        $ATTACKS"
echo "Device:         CUDA:$DEVICE | Batch: $BATCH | ImgSz: $IMGSZ"
echo "Project Dir:    $PROJECT"
echo "Log File:       $LOG_FILE"
echo "=========================================================="

read -r -a ATTACK_LIST <<< "$ATTACKS"

for ATK in "${ATTACK_LIST[@]}"; do
  echo ""
  echo "----------------------------------------------------------"
  echo ">>> [$(date +%T)] Starting evaluation for attack: $ATK ($ATT_SRC_TAG)"
  echo "----------------------------------------------------------"

  RUN_NAME="adaptive_${ATK}_${ATT_SRC_TAG}"

  VAL_CMD=(
    python -u val_adv_run.py
    --weights "$WEIGHTS"
    --data "$DATA"
    --classes "${CLASSES[@]}"
    --attack_weights "$ATTACK_WEIGHTS"
    --attack_name "$ATK"
    --worstk_k "$WORSTK_K"
    --batch "$BATCH"
    --imgsz "$IMGSZ"
    --device "$DEVICE"
    --project "$PROJECT"
    --name "$RUN_NAME"
  )

  echo "Command: ${VAL_CMD[*]}"
  "${VAL_CMD[@]}"

  echo ">>> Completed attack: $ATK"
done

echo ""
echo "=========================================================="
echo "All validations completed successfully at: $(date)"
echo "Results saved under: $PROJECT"
echo "Log saved to:        $LOG_FILE"
echo "=========================================================="
